import {foundations} from './data/foundations.js';
import {backgrounds,learningTracks} from './data/learning-paths.js';
import {codeAccepted} from './daily-state.js';
export function normalizeLearner(value){return {background:backgrounds.some(b=>b.id===value?.background)?value.background:'explore',track:learningTracks.some(t=>t.id===value?.track)?value.track:'all',weeklyHours:[3,6,10].includes(value?.weeklyHours)?value.weeklyHours:6};}
export function normalizeFoundations(value){const out={};for(const lesson of foundations){const r=value?.[lesson.id];if(!r||typeof r!=='object')continue;const answers={};lesson.checks.forEach((q,i)=>{const n=r.answers?.[i];if(Number.isInteger(n)&&n>=0&&n<q.options.length)answers[i]=n;});out[lesson.id]={answers,note:typeof r.note==='string'?r.note.slice(0,12000):'',completedAt:typeof r.completedAt==='string'?r.completedAt.slice(0,50):''};}return out;}
export function foundationStatus(lesson,state,exercises){const record=state.foundations?.[lesson.id]||{},exercise=exercises.find(ex=>ex.id===lesson.exerciseId),correct=lesson.checks.filter((q,i)=>record.answers?.[i]===q.answer).length,code=!!exercise&&codeAccepted(exercise,state),note=typeof record.note==='string'&&record.note.trim().length>=20,ready=correct===lesson.checks.length&&code&&note;return {correct,code,note,ready,complete:ready&&!!record.completedAt,missing:[...(correct<lesson.checks.length?['理解检查']:[]),...(!code?['当前代码的全部检查']:[]),...(!note?['至少 20 字实验观察']:[])]};}
export function learningRecommendation(state,exercises){const next=foundations.find(l=>!foundationStatus(l,state,exercises).complete);if(next)return {href:`#/foundations/${next.id}`,label:`公共入门：${next.title}`};return state.learner?.track!=='all'&&learningTracks.some(t=>t.id===state.learner?.track)?{href:`#/paths/${state.learner.track}`,label:`进入${learningTracks.find(t=>t.id===state.learner.track).name}方向`}:{href:'#/paths',label:'选择一个应用方向'};}
